<?php
declare(strict_types=1);
const VF_ADMIN_EMAIL='yohanaelisha164@gmail.com';
function envv(string $k, ?string $d=null): ?string {$v=getenv($k);return ($v===false||$v==='')?$d:$v;}
function h(string $s): string{return htmlspecialchars($s,ENT_QUOTES,'UTF-8');}
function cfg(string $k,string $d=''): string {$v=envv($k,$d);if($v==='')throw new RuntimeException("Missing environment variable: $k");return $v;}
function project_id(): string{return cfg('FIREBASE_PROJECT_ID','videofunds-project');}
function api_key(): string{return cfg('FIREBASE_API_KEY');}
function service_account(): array {$a=json_decode(cfg('FIREBASE_SERVICE_ACCOUNT_JSON'),true);if(!is_array($a)||empty($a['client_email'])||empty($a['private_key']))throw new RuntimeException('Invalid FIREBASE_SERVICE_ACCOUNT_JSON');return $a;}
function access_token(): string {
 $sa=service_account();$b64=fn($v)=>rtrim(strtr(base64_encode($v),'+/','-_'),'=');$n=time();$head=$b64(json_encode(['alg'=>'RS256','typ'=>'JWT']));$claim=$b64(json_encode(['iss'=>$sa['client_email'],'scope'=>'https://www.googleapis.com/auth/datastore https://www.googleapis.com/auth/identitytoolkit','aud'=>'https://oauth2.googleapis.com/token','iat'=>$n,'exp'=>$n+3500]));$u="$head.$claim";$key=openssl_pkey_get_private($sa['private_key']);if(!$key||!openssl_sign($u,$sig,$key,OPENSSL_ALGO_SHA256))throw new RuntimeException('Service account signing failed');$ch=curl_init('https://oauth2.googleapis.com/token');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>http_build_query(['grant_type'=>'urn:ietf:params:oauth:grant-type:jwt-bearer','assertion'=>$u.'.'.$b64($sig)]),CURLOPT_HTTPHEADER=>['Content-Type: application/x-www-form-urlencoded'],CURLOPT_TIMEOUT=>20]);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$r=json_decode((string)$raw,true);if($code!==200||empty($r['access_token']))throw new RuntimeException('Google OAuth token failed: '.($r['error_description']??$r['error']??'unknown'));return $r['access_token'];
}
function fs(string $method,string $path,?array $body=null): array {$url='https://firestore.googleapis.com/v1/projects/'.rawurlencode(project_id()).'/databases/(default)/documents/'.$path;$headers=['Authorization: Bearer '.access_token()];if($body!==null)$headers[]='Content-Type: application/json';$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_HTTPHEADER=>$headers,CURLOPT_TIMEOUT=>25]);if($body!==null)curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($body));$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);$err=curl_error($ch);curl_close($ch);$data=json_decode((string)$raw,true)?:[];if($raw===false||$code>=400)throw new RuntimeException('Firestore HTTP '.$code.': '.($data['error']['message']??$err));return $data;}
function decode_fields(array $f): array {$o=[];foreach($f as $k=>$v){foreach(['stringValue','integerValue','doubleValue','booleanValue','timestampValue'] as $t)if(array_key_exists($t,$v)){$o[$k]=match($t){'integerValue'=>(int)$v[$t],'doubleValue'=>(float)$v[$t],'booleanValue'=>(bool)$v[$t],default=>$v[$t]};break;}}return $o;}
function typed_fields(array $f): array {$o=[];foreach($f as $k=>$v){$o[$k]=is_bool($v)?['booleanValue'=>$v]:(is_int($v)?['integerValue'=>(string)$v]:(is_float($v)?['doubleValue'=>$v]:['stringValue'=>(string)$v]));}return ['fields'=>$o];}
function auth_call(string $method,array $payload): array {$url='https://identitytoolkit.googleapis.com/v1/projects/'.rawurlencode(project_id()).'/'.$method.'?key='.rawurlencode(api_key());$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($payload),CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.access_token()],CURLOPT_TIMEOUT=>25]);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$r=json_decode((string)$raw,true)?:[];if($code>=400)throw new RuntimeException('Firebase Auth: '.($r['error']['message']??'action failed'));return $r;}
function require_admin(): void {if(empty($_SESSION['vf_admin'])||strtolower((string)($_SESSION['vf_admin_email']??''))!==VF_ADMIN_EMAIL||time()-(int)($_SESSION['vf_admin_login_at']??0)>28800){$_SESSION=[];session_destroy();header('Location: /admin/login.php');exit;}}
function csrf_token(): string {if(empty($_SESSION['vf_csrf']))$_SESSION['vf_csrf']=bin2hex(random_bytes(24));return $_SESSION['vf_csrf'];}
function check_csrf(): void {if(!hash_equals(csrf_token(),(string)($_POST['csrf']??'')))throw new RuntimeException('CSRF validation failed');}
function audit(string $action,string $uid='',array $extra=[]): void {try{$id=bin2hex(random_bytes(12));fs('PATCH','admin_audit/'.$id,typed_fields(['action'=>$action,'target_uid'=>$uid,'admin_email'=>VF_ADMIN_EMAIL,'details'=>json_encode($extra),'created_at'=>gmdate('c')]));}catch(Throwable $e){error_log('audit: '.$e->getMessage());}}
function get_user(string $uid): array {$d=fs('GET','users/'.rawurlencode($uid));return ['uid'=>$uid,'profile'=>decode_fields($d['fields']??[])];}
function list_users(): array {
 $ch=curl_init('https://identitytoolkit.googleapis.com/v1/projects/'.rawurlencode(project_id()).'/accounts:batchGet?maxResults=1000');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.access_token()],CURLOPT_TIMEOUT=>25]);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$r=json_decode((string)$raw,true)?:[];if($code>=400)throw new RuntimeException('Cannot list Firebase Auth users: '.($r['error']['message']??$code));
 $docs=fs('GET','users?pageSize=1000')['documents']??[];$profiles=[];foreach($docs as $d)$profiles[basename($d['name'])]=decode_fields($d['fields']??[]);$out=[];foreach(($r['users']??[]) as $u){$id=$u['localId'];$p=$profiles[$id]??[];$out[]=['uid'=>$id,'email'=>$u['email']??$p['email']??'','name'=>$p['fullname']??$u['displayName']??'—','balance'=>$p['balance']??0,'referral'=>$p['referral_code']??'','referred_by'=>$p['referred_by']??'','disabled'=>(bool)($u['disabled']??false),'created'=>$u['createdAt']??''];}return $out;
}
